INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11236, 62276, 'tt0381936', NULL, 'Bimmer', 'Бумер', 'movie', 2003, 'https://image.tmdb.org/t/p/w500/ukaoIeNfqXbNM0zvUSaRpPaDJoi.jpg', 'https://image.tmdb.org/t/p/original/hkRBphefeefAq4Q9sqiOtGv2YdS.jpg', 'A black BMW, a symbol of luxury, is racing along the night streets of Moscow in the 90s. Bad luck turns four friends into criminals and they have no way back. Only the black “bimmer” is reliable in this life without rules, taking the friends farther and farther from Moscow, into the crazy and ruthless wilderness of Russian roads… None of them wanted to kill. None of them wanted to die. But they will have to face their destiny in the end.', NULL, NULL, 1.3328, 6.212, 0, 8.01, '2026-08-22 01:37:44', '2026-08-22 01:37:44');
