INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11238, 411999, 'tt4693358', NULL, 'OtherLife', 'OtherLife', 'movie', 2017, 'https://image.tmdb.org/t/p/w500/stSDsKsb4fS6NPzuHwfAWD2jim8.jpg', 'https://image.tmdb.org/t/p/original/arb8T0YFfLT5cUVIJPTMoHbmk12.jpg', 'Ren Amari is the driven inventor of a revolutionary new drug. OtherLife expands the brain''s sense of time and creates virtual reality directly in the user''s mind. With OtherLife, mere seconds in real life feel like hours or days of exciting adventures. As Ren and her colleagues race around the clock to launch OtherLife, the government muscles in to use the drugs as a radical solution to prison overcrowding. They will create virtual cells where criminals serve long sentences in just minutes of real time. When Ren resists, she finds herself an unwilling guinea pig trapped in a prison cell in her mind. She must escape before she descends into madness, and then regain control of OtherLife before others suffer the same fate.', NULL, NULL, 2.1645, 6.412, 0, 8.51, '2026-08-22 01:37:44', '2026-08-22 01:37:44');
