INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11243, 294272, 'tt2788732', NULL, 'Pete''s Dragon', 'Pete''s Dragon', 'movie', 2016, 'https://image.tmdb.org/t/p/w500/A9x4Ogk8KUXTfU649NS6lS9TCmu.jpg', 'https://image.tmdb.org/t/p/original/ct9S0m2U2RTCFAVnq3y0nF0Tgb2.jpg', 'For years, old wood carver Mr. Meacham has delighted local children with his tales of the fierce dragon that resides deep in the woods of the Pacific Northwest. To his daughter, Grace, who works as a forest ranger, these stories are little more than tall tales... until she meets Pete, a mysterious 10-year-old with no family and no home who claims to live in the woods with a giant, green dragon named Elliott. And from Pete''s descriptions, Elliott seems remarkably similar to the dragon from Mr. Meacham''s stories. With the help of Natalie, an 11-year-old girl whose father Jack owns the local lumber mill, Grace sets out to determine where Pete came from, where he belongs, and the truth about this dragon.', NULL, NULL, 7.0877, 6.391, 0, 8.02, '2026-08-22 01:37:44', '2026-08-22 01:37:44');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11244, 72340, 'tt6853528', NULL, 'Little Women', 'Little Women', 'tv', 2017, 'https://image.tmdb.org/t/p/w500/6qzMhtTyNwpaAthrAbojojfHWrs.jpg', 'https://image.tmdb.org/t/p/original/hQAFYlWxwZntIo5LLJAMOxjN21y.jpg', 'Set against the backdrop of the American Civil War, the story follows sisters Jo, Meg, Beth and Amy March on their journey from childhood to adulthood. With the help of their mother, Marmee, and while their father is away at war, the girls navigate what it means to be a young woman: from sibling rivalry and first love, to loss and marriage.', NULL, NULL, 5.4871, 7.179, 0, 11.03, '2026-08-22 01:37:44', '2026-08-22 01:37:44');
