INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11250, 40293, 'tt2094262', NULL, 'Da Vinci''s Demons', 'Da Vinci''s Demons', 'tv', 2013, 'https://image.tmdb.org/t/p/w500/sR8m3EUxmRJi4S9u5sfBDRLce1Z.jpg', 'https://image.tmdb.org/t/p/original/wHcLMdK85CIJu76RNxnq6rhS2FF.jpg', 'The series follows the "untold" story of Leonardo Da Vinci: the genius during his early years in Renaissance Florence. As a 25-year old artist, inventor, swordsman, lover, dreamer and idealist, he struggles to live within the confines of his own reality and time as he begins to not only see the future, but invent it.', NULL, NULL, 11.0223, 7.55, 0, 1.02, '2026-08-22 01:37:44', '2026-08-22 01:37:44');
