INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11253, 712637, 'tt0447379', NULL, 'The Red Violin', 'Punane viiul', 'movie', 1975, 'https://image.tmdb.org/t/p/w500/ytwlKaa8kgs32OPKNPM7KSJA2e2.jpg', 'https://image.tmdb.org/t/p/original/AsS54navKWKuLl8H9Yfno52uajB.jpg', 'When Estonian violinist Eduard Sõrmus starts his concert tours in Europe, he is convinced that the world revolution is about to begin. His mission as a Red Violinist is to call the proletariat around the world to join with the revolution. It is only two things - music and revolution - that Eduard has dedicated himself to. His audience is enchanted by his performance and ignited by his ideas. With this knowledge, he travels Europe between the two world wars, accompanied by his faithful friends, his audience''s admiration and the hostility of the authorities.', NULL, NULL, 1.0723, 9.0, 0, 3.0166666666666666e+00, '2026-08-22 01:37:44', '2026-08-22 01:37:44');
