INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11291, 283566, 'tt2458948', NULL, 'Evangelion: 3.0+1.0 Thrice Upon a Time', 'シン・エヴァンゲリオン劇場版:||', 'movie', 2021, 'https://image.tmdb.org/t/p/w500/md5wZRRj8biHrGtyitgBZo7674t.jpg', 'https://image.tmdb.org/t/p/original/1EAxNqdkVnp48a7NUuNBHGflowM.jpg', 'In the aftermath of the Fourth Impact, stranded without their Evangelions, Shinji, Asuka and Rei find refuge in one of the rare pockets of humanity that still exist on the ruined planet Earth. There, each lives a life far different from their days as an Evangelion pilot. However, the danger to the world is far from over. A new impact is looming on the horizon—one that will prove to be the true end of Evangelion.', NULL, NULL, 9.6445, 8.213, 0, 7.01, '2026-08-22 01:37:44', '2026-08-22 01:37:44');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11292, 15137, 'tt0923811', NULL, 'Evangelion: 1.0 You Are (Not) Alone', 'ヱヴァンゲリヲン新劇場版：序', 'movie', 2007, 'https://image.tmdb.org/t/p/w500/pETU4GurpeEjBOM8oytMH0yNBHx.jpg', 'https://image.tmdb.org/t/p/original/ktzhr2m6y98PtwOdfOtTA0X232m.jpg', 'After the Second Impact, Tokyo-3 is being attacked by giant monsters called Angels that seek to eradicate humankind. The child Shinji’s objective is to fight the Angels by piloting one of the mysterious Evangelion mecha units. A remake of the first six episodes of GAINAX’s famous 1996 anime series. The film was retitled “Evangelion: 1.01” for its DVD release and “Evangelion: 1.11” for a release with additional scenes.', NULL, NULL, 5.7568, 7.604, 0, 7.01, '2026-08-22 01:37:44', '2026-08-22 01:37:44');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11293, NULL, NULL, 102584, 'Dying Light 2: Stay Human', 'Dying Light 2: Stay Human', 'game', 2022, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co65yk.jpg', NULL, 'The last great human settlement exists within an unforgiving, infected world. Exceptional agility and combat skills make you a powerful ally and a valuable commodity. With your unique abilities you have the power to be an agent of change within this decaying metropolis. Use it wisely.', 'https://www.igdb.com/games/dying-light-2-stay-human', '["Xbox Series X|S", "PlayStation 4", "PC (Microsoft Windows)", "PlayStation 5", "Xbox One"]', NULL, NULL, 0, 10.01, '2026-08-22 01:37:44', '2026-08-22 01:37:44');
