INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11310, 606523, 'tt12792418', NULL, 'Night in Paradise', '낙원의 밤', 'movie', 2020, 'https://image.tmdb.org/t/p/w500/dYCWUAidqgakGETwZkfGxU7CWhL.jpg', 'https://image.tmdb.org/t/p/original/MocpW8Wrp8uireBg6bT6Y6TKWC.jpg', 'An assassin named Tae-goo is offered a chance to switch sides with his rival Bukseong gang, headed by Chairman Doh. Tae-goo rejects the offer that results in the murder of his sister and niece. In revenge, Tae-goo brutally kills Chairman Doh and his men and flees to Jeju Island where he meets Jae-yeon, a terminally ill woman. Though, the henchman of the Bukseong gang, Executive Ma is mercilessly hunting Tae-goo to take revenge.', NULL, NULL, 3.8742, 6.928, 0, 6.51, '2026-08-22 01:37:44', '2026-08-22 01:37:44');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11311, NULL, NULL, 9927, 'Persona 5', 'Persona 5', 'game', 2016, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1r76.jpg', NULL, 'Persona 5, a turn-based JRPG with visual novel elements, follows a high school student with a criminal record for a crime he didn''t commit. Soon he meets several characters who share similar fates to him, and discovers a metaphysical realm which allows him and his friends to channel their pent-up frustrations into becoming a group of vigilantes reveling in aesthetics and rebellion while fighting corruption.', 'https://www.igdb.com/games/persona-5', '["PlayStation 3", "PlayStation 4"]', NULL, NULL, 0, 6.51, '2026-08-22 01:37:44', '2026-08-22 01:37:44');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11312, 19076, 'tt0242252', NULL, 'The Affair of the Necklace', 'The Affair of the Necklace', 'movie', 2001, 'https://image.tmdb.org/t/p/w500/uPgXAA5PzMCCWXYA3PsihgNkwht.jpg', 'https://image.tmdb.org/t/p/original/woxo93Jbp2B5wfd4zfS6B2phJNW.jpg', 'In pre-Revolutionary France, a young aristocratic woman left penniless by the political unrest in the country, must avenge her family''s fall from grace by scheming to steal a priceless necklace.', NULL, NULL, 2.2563, 5.616, 0, 8.065, '2026-08-22 01:37:44', '2026-08-22 01:37:44');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11313, 64353, 'tt3830558', NULL, 'Versailles', 'Versailles', 'tv', 2015, 'https://image.tmdb.org/t/p/w500/fMqCRNpc2FadD0n7vJLRmlS0aEt.jpg', 'https://image.tmdb.org/t/p/original/cWe83yD8s7B1OZ71ntIS5fCeqWC.jpg', 'The story of a young Louis XIV on his journey to become the most powerful monarch in Europe, from his battles with the fronde through his development into the Sun King. Historical and fictional characters guide us in a world of betrayal and political maneuvering, revealing Versailles in all its glory and brutality.', NULL, NULL, 11.7714, 7.657, 0, 6.08, '2026-08-22 01:37:44', '2026-08-22 01:37:44');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11314, 69541, 'tt5761478', NULL, 'Harlots', 'Harlots', 'tv', 2017, 'https://image.tmdb.org/t/p/w500/w6F93B2ZUCEUhRpgCS1cU82htqz.jpg', 'https://image.tmdb.org/t/p/original/rIlzpqYjgnLl0GkUIVNzw6c9dWa.jpg', 'Brothel owner, Margaret Wells, struggles to raise her daughters in London during the 18th century.', NULL, NULL, 9.566, 7.334, 0, 5.52, '2026-08-22 01:37:44', '2026-08-22 01:37:44');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11315, 37606, 'tt0098575', NULL, 'Valmont', 'Valmont', 'movie', 1989, 'https://image.tmdb.org/t/p/w500/AuCnhQII6ZNgRDrr2N5KyDCnhnj.jpg', 'https://image.tmdb.org/t/p/original/upZUY8Tj9RHHLKPpGKU40qQ0Y1R.jpg', 'Set in Baroque France, a scheming widow and her lover make a bet regarding the corruption of a recently married woman. The lover, Valmont, bets that he can seduce her, even though she is an honorable woman. If he wins, he can have his lover to do as he will. However, in the process of seducing the married woman, Valmont falls in love.', NULL, NULL, 4.4405, 6.718, 0, 5.01, '2026-08-22 01:37:44', '2026-08-22 01:37:44');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11316, 627346, 'tt0008241', NULL, 'Madame du Barry', 'Madame du Barry', 'movie', 1917, 'https://image.tmdb.org/t/p/w500/swurvopFe1yqBTzouS1EmUoJP9.jpg', 'https://image.tmdb.org/t/p/original/9wA1KD2gByV7opQ07ZDRlNXGtGx.jpg', 'After Jeanette becomes the mistress of the ambitious Jean du Barry, he marries her off to one of his cousins so that she has an entre to the royal court. She soon becomes the favorite of the King and Jean du Barry becomes a regular around the court too. But all this is disturbed when Madame du Barry falls for Conte Brissac of the King''s Guard. Jean du Barry''s attempts to expose her affair only get him banished from the court.', NULL, NULL, 0.7302, 7.0, 0, 5.01, '2026-08-22 01:37:44', '2026-08-22 01:37:44');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11317, 7093, 'tt0190861', NULL, 'Vatel', 'Vatel', 'movie', 2000, 'https://image.tmdb.org/t/p/w500/qxtzOlO5FqFgSOGnNr0kFzo2Ho7.jpg', 'https://image.tmdb.org/t/p/original/jjogwfWVmwc4l0iNEmxXdz9fXKU.jpg', 'In 1671, with war brewing with Holland, a penniless prince invites Louis XIV to three days of festivities at a chateau in Chantilly. The prince wants a commission as a general, so the extravagances are to impress the king. In charge of all is the steward, Vatel, a man of honor, talent, and low birth. The prince is craven in his longing for stature: no task is too menial or dishonorable for him to give Vatel. While Vatel tries to sustain dignity, he finds himself attracted to Anne de Montausier, the king''s newest mistress. In Vatel, she finds someone who''s authentic, living out his principles within the casual cruelties of court politics. Can the two of them escape unscathed?', NULL, NULL, 2.0133, 6.138, 0, 5.01, '2026-08-22 01:37:44', '2026-08-22 01:37:44');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11318, 38486, 'tt1521186', NULL, 'Maison close', 'Maison close', 'tv', 2010, 'https://image.tmdb.org/t/p/w500/3cVBJ4lrAiVJp6Lwuvzapc4Uzqh.jpg', 'https://image.tmdb.org/t/p/original/gMyX8zlNuiVCtkVe4aQAGr5djda.jpg', 'Paris, 1871. This is a story of the women trapped in a luxury brothel, ''Paradise''. The very young Rose came to Paris in search of her mother, former prostitute. She is trapped and forced to enroll in Paradise. Vera is 35 years. She knows that the end of her career as a prostitute is near. She is betting everything on the Baron Du Plessis, her main client, and the only one able to redeem her debt. Hortense is the owner of Paradise. She must take care of her girls and resist pressure from a suburban thug who is charging her money.', NULL, NULL, 3.6214, 6.429, 0, 4.01, '2026-08-22 01:37:44', '2026-08-22 01:37:44');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11319, 84427, 'tt1660379', NULL, 'House of Pleasures', 'L''Apollonide, souvenirs de la maison close', 'movie', 2011, 'https://image.tmdb.org/t/p/w500/adkiqkEOKW8nMlfF8hVcaPWTAwB.jpg', 'https://image.tmdb.org/t/p/original/rVbpucPpRyFXYV73AiCOrKknNJw.jpg', 'The dawn of the 20th century: L’Apollonide, a luxurious and traditional brothel in Paris, is living its last days. In this closed world, where some men fall in love and others become viciously harmful, the women share their secrets, their fears, their joys and their pains.', NULL, NULL, 3.6989, 6.467, 0, 4.01, '2026-08-22 01:37:44', '2026-08-22 01:37:44');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11320, 352733, 'tt4184252', NULL, 'The Scandalous Lady W', 'The Scandalous Lady W', 'movie', 2015, 'https://image.tmdb.org/t/p/w500/ekegcpp9Ri1R4slhtJrJwT4Euw0.jpg', 'https://image.tmdb.org/t/p/original/qPUj59haWS8XoFZ4LV056YcC33C.jpg', 'A gripping 18th century drama details the scandalous life of Lady Seymour Worsley, who dared to leave her husband and elope with his best friend, Captain George Bisset. Lady Seymour Worsley escapes her troubled marriage only to find herself at the centre of a very public trial brought by her powerful husband Sir Richard Worsley.', NULL, NULL, 2.4586, 6.579, 0, 4.01, '2026-08-22 01:37:44', '2026-08-22 01:37:44');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11321, NULL, NULL, 2853, 'Braid', 'Braid', 'game', 2008, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co25ni.jpg', NULL, 'Braid is a puzzle-platformer, drawn in a painterly style, where you can manipulate the flow of time in strange and unusual ways. From a house in the city, journey to a series of worlds and solve puzzles to rescue an abducted princess. In each world, you have a different power to affect the way time behaves, and it is time''s strangeness that creates the puzzles. The time behaviors include: the ability to rewind, objects that are immune to being rewound, time that is tied to space, parallel realities, time dilation, and perhaps more.

Braid treats your time and attention as precious; there is no filler in this game. Every puzzle shows you something new and interesting about the game world.', 'https://www.igdb.com/games/braid', '["PlayStation 3", "Linux", "PC (Microsoft Windows)", "Mac", "Xbox 360"]', NULL, NULL, 0, 4.01, '2026-08-22 01:37:44', '2026-08-22 01:37:44');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11322, 502805, 'tt3759912', NULL, 'Ladyworld', 'Ladyworld', 'movie', 2019, 'https://image.tmdb.org/t/p/w500/zSnPyXrayan8JlPFJin2VBeGdBp.jpg', 'https://image.tmdb.org/t/p/original/osc9hWKeXwr2xfrWCto8dUwBGLf.jpg', 'After a catastrophic event, eight girls find themselves stranded in a house without electricity. As they run out of food and water, their sanity begins to crumble, and soon they regress to their baser instincts.', NULL, NULL, 0.7936, 4.667, 0, 3.51, '2026-08-22 01:37:44', '2026-08-22 01:37:44');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11323, NULL, NULL, 250, 'The Chronicles of Riddick: Escape from Butcher Bay', 'The Chronicles of Riddick: Escape from Butcher Bay', 'game', 2004, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1mp7.jpg', NULL, 'Escape from Butcher Bay is set in the futuristic science fiction universe of the Chronicles of Riddick franchise, and is a prequel to the film Pitch Black. The game takes place inside Butcher Bay, a maximum-security prison from which no prisoner has escaped. The facility - constructed on a barren planet - contains three increasingly secure holding areas, and a subterranean mining operation.', 'https://www.igdb.com/games/the-chronicles-of-riddick-escape-from-butcher-bay', '["Xbox", "PlayStation 3", "PC (Microsoft Windows)", "Mac", "Xbox 360"]', NULL, NULL, 0, 1.26533333333333324e+01, '2026-08-22 01:37:44', '2026-08-22 01:37:44');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11324, 10447, 'tt0110678', NULL, 'No Escape', 'No Escape', 'movie', 1994, 'https://image.tmdb.org/t/p/w500/jRwMdEb5bxwVARU2VmOADTflLfZ.jpg', 'https://image.tmdb.org/t/p/original/jVgQzfKgJ7kCvviscQXpSPD208X.jpg', 'In the year 2022, a ruthless prison warden has created the ultimate solution for his most troublesome and violent inmates: Absolom, a secret jungle island where prisoners are abandoned and left to die. But Marine Captain John Robbins, convicted of murdering a commanding officer, is determined to escape the island in order to reveal the truth behind his murderous actions and clear his name.', NULL, NULL, 2.581, 6.2, 0, 8.52, '2026-08-22 01:37:44', '2026-08-22 01:37:44');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11325, NULL, NULL, 1939, 'Destiny', 'Destiny', 'game', 2014, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1rco.jpg', NULL, 'Bungie has emphasized that the universe of Destiny will be "alive". Events may happen in-game that are not necessarily controlled or planned by the developer, which will help to create a dynamic developing experience for Bungie and a dynamic playing experience for gamers. The game''s style has been described a first-person shooter that will incorporate massively multiplayer online game (MMO) elements, but Bungie has avoided defining Destiny as a traditional MMO game. Instead, the game has been referred to as a "shared-world shooter," as it lacks many of the characteristics of a traditional MMO game. For instance, rather than players being able to see and interact with all other players in the game or on a particular server—as is the case in many conventional MMO games—Destiny will include on-the-fly matchmaking that will allow players to see and interact only with other players with whom they are "matched" by the game.
Destiny will incorporate a new game engine that allows global illuminations and real-time dynamic lighting to occur together. An innovation in Bungie''s "hopper" technology, which has been the backbone for Halo''s matchmaking system, will allow better player matchmaking in order to create a more natural experience in either cooperative or competitive multiplayer modes.', 'https://www.igdb.com/games/destiny', '["PlayStation 3", "PlayStation 4", "Xbox 360", "Xbox One"]', NULL, NULL, 0, 9.56, '2026-08-22 01:37:44', '2026-08-22 01:37:44');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11326, NULL, NULL, 24054, 'Caves of Qud', 'Caves of Qud', 'game', 2024, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7eda.jpg', NULL, 'Caves of Qud is a science fantasy roguelike epic steeped in retro-futurism, deep simulation, and swathes of sentient plants. The game weaves a handwritten narrative through rich physical, social, and historical simulations. The result is a hybrid handcrafted & procedurally-generated world where you can do just about anything. Assemble your character from over 70 mutations and defects, and 24 castes and kits - it’s all the character diversity you could want. Explore procedurally-generated regions with some familiar locations - each world is nearly 1 million maps large.', 'https://www.igdb.com/games/caves-of-qud', '["Linux", "PC (Microsoft Windows)", "Mac", "Nintendo Switch"]', NULL, NULL, 0, 9.04, '2026-08-22 01:37:44', '2026-08-22 01:37:44');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11327, 25466, 'tt0106215', NULL, 'Mutant Action', 'Acción mutante', 'movie', 1993, 'https://image.tmdb.org/t/p/w500/dVbouY3L2iVr0qfOlbxuUQH7yA1.jpg', 'https://image.tmdb.org/t/p/original/n7jIsZoAjY69DCs0BmZBEaEzg5R.jpg', 'Waging war against all things glamorous and beautiful, crippled terrorists Acción Mutante plot a series of attacks on society''s elite, and attempt the kidnapping of a wealthy socialite at her elaborate wedding reception.', NULL, NULL, 1.5227, 6.256, 0, 9.01, '2026-08-22 01:37:44', '2026-08-22 01:37:44');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11328, NULL, NULL, 320137, 'Cronos: The New Dawn', 'Cronos: The New Dawn', 'game', 2025, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobqq9.jpg', NULL, 'Cronos: The New Dawn is a pulse-pounding, third-person survival horror game that throws you into the heart of a deadly struggle against overwhelming foes, all while uncovering the mysteries of a twisted time travel story.', 'https://www.igdb.com/games/cronos-the-new-dawn', '["Xbox Series X|S", "Linux", "Nintendo Switch 2", "PC (Microsoft Windows)", "PlayStation 5"]', NULL, NULL, 0, 9.02, '2026-08-22 01:37:44', '2026-08-22 01:37:44');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11329, NULL, NULL, 2990, 'Machinarium', 'Machinarium', 'game', 2009, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co27lo.jpg', NULL, 'Machinarium is award-winning independent adventure game developed by the makers of Samorost and Botanicula. A little robot who’s been thrown out to the scrap yard behind the city must return and confront the Black Cap Brotherhood and save his robot-girl friend.', 'https://www.igdb.com/games/machinarium', '["PlayStation 3", "PlayStation 4", "Linux", "Android", "PC (Microsoft Windows)", "iOS", "Mac", "PlayStation Vita", "Xbox One", "Nintendo Switch"]', NULL, NULL, 0, 8.51, '2026-08-22 01:37:44', '2026-08-22 01:37:44');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11330, NULL, NULL, 7386, 'The Talos Principle', 'The Talos Principle', 'game', 2014, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1rb5.jpg', NULL, 'The Talos Principle is a philosophical first-person puzzle game from Croteam, the creators of the legendary Serious Sam series, written by Tom Jubert (FTL, The Swapper) and Jonas Kyratzes (The Sea Will Claim Everything).', 'https://www.igdb.com/games/the-talos-principle', '["PlayStation 4", "Linux", "Android", "PC (Microsoft Windows)", "iOS", "Mac", "Xbox One", "Nintendo Switch"]', NULL, NULL, 0, 8.51, '2026-08-22 01:37:44', '2026-08-22 01:37:44');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11331, NULL, NULL, 1865, 'Killzone', 'Killzone', 'game', 2004, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3ko7.jpg', NULL, 'Killzone is a sci-fi-themed first-person shooter. The game''s stand-out feature is the ability to control any of the four different protagonists, each with his or her own strengths and weaknesses. Up to sixteen players could compete in the online multiplayer portion, which includes eight maps and six modes: Deathmatch, Team Deathmatch, Assault, Defend and Destroy, Supply Drop, and Domination. The online servers of the game have now been closed down.', 'https://www.igdb.com/games/killzone', '["PlayStation 2"]', NULL, NULL, 0, 8.51, '2026-08-22 01:37:44', '2026-08-22 01:37:44');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11332, NULL, NULL, 3277, 'Rust', 'Rust', 'game', 2018, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coajjj.jpg', NULL, 'Rust is a multiplayer survival game set on a procedurally generated island where players must manage hunger, thirst, and health while contending with hostile wildlife and other players. Starting with only a rock and torch, players gather resources, craft tools, weapons, and structures, and form or fight against clans in a persistent open world that resets on a regular wipe cycle. Originally developed as a clone of DayZ with Minecraft-style crafting elements, the game spent over four years in early access before its full release in 2018.', 'https://www.igdb.com/games/rust', '["PC (Microsoft Windows)", "Mac"]', NULL, NULL, 0, 8.11, '2026-08-22 01:37:44', '2026-08-22 01:37:44');
