INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11348, 352492, 'tt4855748', NULL, 'XOXO', 'XOXO', 'movie', 2016, 'https://image.tmdb.org/t/p/w500/5hbTuc8Lbw7N8RwMOc9bjAcSjuw.jpg', 'https://image.tmdb.org/t/p/original/8veRW9Hb3cQZgAy28gqvJVo34O1.jpg', 'XOXO follows six strangers whose lives collide in one frenetic, dream-chasing, hopelessly romantic night.', NULL, NULL, 1.4537, 5.944, 0, 10.02, '2026-08-22 01:37:44', '2026-08-22 01:37:44');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11349, 1720, 'tt0419326', NULL, 'Foster''s Home for Imaginary Friends', 'Foster''s Home for Imaginary Friends', 'tv', 2004, 'https://image.tmdb.org/t/p/w500/kj6oGL4qqFDY8PGmTloqGQ2TblS.jpg', 'https://image.tmdb.org/t/p/original/ccQm8pihskN0lCYwjQEt8sjBHZq.jpg', 'What happens when a child outgrows his trusty Imaginary Friend, the pal that stuck with him through all of the highs and lows of growing up? Well, these creations pack up and head for Foster''s Home for Imaginary Friends! Foster''s is a one-of-a-kind Victorian mansion filled with hundreds of unique characters from all over the world, thought up by completely different children for completely different reasons. These creatures all live together in this vast, sprawling home with more rooms than you could ever dream possible! Mac, a clever but somewhat shy 8-year-old boy, discovers Foster''s when his mom tells him he''s too old for his Imaginary Friend Blooregard. Not ready to part with his trouble making best buddy, Mac takes Bloo to Foster''s with the hope of giving him a safe place to live, while still being able to visit every day.', NULL, NULL, 92.9455, 7.8, 0, 1.12, '2026-08-22 01:37:44', '2026-08-22 01:37:44');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11350, 255, 'tt0407398', NULL, 'Hi Hi Puffy AmiYumi', 'Hi Hi Puffy AmiYumi', 'tv', 2004, 'https://image.tmdb.org/t/p/w500/dVlsQzfxewEdHpu7SiVUpRAVNyU.jpg', 'https://image.tmdb.org/t/p/original/16JZ5IRrA9YSxVSqWflY0nLhLwz.jpg', 'Hi Hi Puffy AmiYumi follows the adventures of two very cool, but very different pop stars as they travel from gig to gig or just hang out in their tour bus. Being famous rock stars, Ami and Yumi tour the globe in their customized Puffy bus, a veritable condo on wheels with all the major amenities and an ever-changing interior. Ami is the peppy, positive, and resourceful one. Yumi is the hard-rocking, no-nonsense cynic with an absolutely infallible sense of cool. Together, these superstars take the world by storm with musical talent, trend-setting style and humor, despite occasional misjudgments from their well-meaning but tragically square manager, Kaz.', NULL, NULL, 9.899, 7.373, 0, 1.1, '2026-08-22 01:37:44', '2026-08-22 01:37:44');
