INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11356, 6907, 'tt1015453', NULL, 'Sushi Pack', 'Sushi Pack', 'tv', 2007, 'https://image.tmdb.org/t/p/w500/q2r584MO0z62cRn23tCGFjeyz6E.jpg', 'https://image.tmdb.org/t/p/original/iktXjT0YbHbZLcoxKIHG5zFvUPq.jpg', 'Sushi Pack is an American-Canadian animated television series produced by DIC Entertainment and American Greetings, that aired on the KEWLopolis block on CBS November 3, 2007 - September 12, 2009. It featured a team of wasabi, salmon egg sushi, crab sushi, tuna sushi, and octopus sushi as they used their wits and their emotions to save the world and educated young children. The Sushi Pack team lives in a donut shop with their human friend, Ben. Despite the superhero element of the story, violence is used only as a last resort. The closing theme song of the show is a techno/rap/funk hybrid song written by Phofo, composer for the entire series. Sushi Pack was created by Studio Espinosa. Quests involve learning about the meaning of friendship, social skills, and teamwork.', NULL, NULL, 3.7641, 10.0, 0, 1.02, '2026-08-22 01:37:44', '2026-08-22 01:37:44');
INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11357, 35372, 'tt1893088', NULL, 'The Problem Solverz', 'The Problem Solverz', 'tv', 2011, 'https://image.tmdb.org/t/p/w500/k2yulLYUNLbe6Gg1jdcZIQiA3pR.jpg', 'https://image.tmdb.org/t/p/original/e4w2GcS4ckP77DzGm6MCMqbW6zc.jpg', 'The Problem Solverz is an American animated television series created by Ben Jones, a member of the art collective Paper Rad, for Cartoon Network. The series centered on the titular Problem Solverz trio of Alfe, Roba, and Horace, as they solve and sometimes create the various problems that plague their town, Farboro. The series is rated TV-PG. The original pilot Neon Knome was rejected by Cartoon Network''s late-night programming block Adult Swim, but was picked up and re-tooled by the main network, which premiered the series on April 4, 2011.

On September 20, 2012, a statement on a Facebook page for the show said that the second half of Season 2 was intended to debut September 24, 2012, but the scheduling was delayed. Selected reruns have been aired during Cartoon Network''s January 2013 revival of their Cartoon Planet variety show.

On March 30, 2013, Season 2 was released only on Netflix.', NULL, NULL, 3.4222, 4.286, 0, 1.01, '2026-08-22 01:37:44', '2026-08-22 01:37:44');
