INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11369, 1440522, NULL, NULL, 'The Barbie Movie', 'The Barbie Movie', 'movie', 2025, 'https://image.tmdb.org/t/p/w500/zsEWRfzNlr7qzZcStaGxeMbihhh.jpg', 'https://image.tmdb.org/t/p/original/9PoBQZxy3taCrD3hI1gJvvDGJyy.jpg', 'Equal parts documentary, visual essay, experimental collage narrative, and parodic homage to and of all things Barbie, this caustic and exciting visual foray embraces the complicated terrain of feminist discourse, cultural criticism, and political rhetoric, as well as insights on gender, identity, and personal experience where all roads lead back to the phenomena that is Barbie.', NULL, NULL, 1.0002, 1.0, 0, 3.93, '2026-08-22 01:37:44', '2026-08-22 01:37:44');
