INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11373, 29380, 'tt0040308', NULL, 'Easter Parade', 'Easter Parade', 'movie', 1948, 'https://image.tmdb.org/t/p/w500/aLgvafQvb6D6at4khC0b7kn0h8f.jpg', 'https://image.tmdb.org/t/p/original/g2MffH3EQXvjSnFF8ol1VkuAKci.jpg', 'On the day before Easter in 1911, Don Hewes is crushed when his dancing partner (and object of affection) Nadine Hale refuses to start a new contract with him. To prove Nadine''s not important to him, Don acquires innocent new protege Hannah Brown, vowing to make her a star in time for next year''s Easter parade.', NULL, NULL, 1.6053, 7.0, 0, 8.01, '2026-08-22 01:37:44', '2026-08-22 01:37:44');
