INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11375, 42257, 'tt0073107', NULL, 'Hester Street', 'Hester Street', 'movie', 1975, 'https://image.tmdb.org/t/p/w500/sEYKnLShvnJuXzYWFI870F1hqZK.jpg', 'https://image.tmdb.org/t/p/original/6PM9BRYYrYTkj0Ez7btxf46t7o0.jpg', 'A Russian emigre prides himself on the way he''s molded himself into a real Yankee in the USA, though the world he lives in, New York''s Lower East Side in the late 19th century, is almost exclusively populated by other Jewish immigrants. When his wife finally arrives in the New World, however, she has a lot of assimilating to do.', NULL, NULL, 1.2826, 6.218, 0, 10.01, '2026-08-22 01:37:44', '2026-08-22 01:37:44');
