INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11378, NULL, NULL, 1083, 'Wipeout', 'Wipeout', 'game', 1995, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4ayj.jpg', NULL, 'Wipeout is a racing game that is set in 2052, where players compete in the F3600 anti-gravity racing league. The game allows the player to pilot one of a selection of craft in races on several different tracks. There are four racing teams to choose from, and two ships for each team. Each ship has its distinct characteristics of acceleration, top speed, mass, and turning radius. By piloting their craft over power-up pads found on the tracks, the player can pick up various weapons and power-ups such as shields, turbo boosts, mines, shock waves, rockets, or missiles. The power-ups allow the player to either protect their craft or disrupt the competitors'' craft.', 'https://www.igdb.com/games/wipeout', '["PlayStation 3", "Android", "DOS", "Sega Saturn", "PlayStation", "PlayStation Portable"]', NULL, NULL, 0, 10.05, '2026-08-22 01:37:44', '2026-08-22 01:37:44');
