INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11387, 44783, 'tt0296881', NULL, 'Symbiopsychotaxiplasm: Take One', 'Symbiopsychotaxiplasm: Take One', 'movie', 1968, 'https://image.tmdb.org/t/p/w500/wMRtQ3A4pOmG2dXKOxx9tTerFi6.jpg', 'https://image.tmdb.org/t/p/original/uYo84MtnPcECYvmNUtEBv2wUrE0.jpg', 'In Manhattan''s Central Park, a film crew directed by William Greaves is shooting a screen test with various pairs of actors. It''s a confrontation between a couple: he demands to know what''s wrong, she challenges his sexual orientation. Cameras shoot the exchange, and another camera records Greaves and his crew. Sometimes we watch the crew discussing this scene, its language, and the process of making a movie. Is there such a thing as natural language? Are all things related to sex? The camera records distractions - a woman rides horseback past them; a garrulous homeless vet who sleeps in the park chats them up. What''s the nature of making a movie?', NULL, NULL, 1.0923, 6.844, 0, 1.01, '2026-08-22 01:37:44', '2026-08-22 01:37:44');
