INSERT OR IGNORE INTO "recommendations" ("id", "tmdb_id", "imdb_id", "igdb_id", "title", "original_title", "media_type", "release_year", "poster_url", "backdrop_url", "overview", "external_url", "platforms", "popularity", "vote_average", "is_ambiguous", "evidence_score", "created_at", "updated_at") VALUES (11389, 511565, 'tt2058057', NULL, 'Private Eyes', 'Private Eyes', 'movie', 2011, 'https://image.tmdb.org/t/p/w500/gZ2QZSQS0QqdMV2m21Flpbyt5qz.jpg', 'https://image.tmdb.org/t/p/original/7j9tjUa6a6bnUqVruVXksmRKviH.jpg', 'Matthew is never afraid of the dark because he has been surrounded by it all his life. He’s got eyes hiding everywhere: in his hands, in his feet and especially in his ears. This week, his mother and father are preparing a surprise for his birthday and he can hardly wait to find out what it is! Directed by Nicola Lemay, Private Eyes is a 3D stereoscopic animated adaptation of Gilles Tibo’s book for children published in 1999 by Éditions Soulières.', NULL, NULL, 0.901, 0.0, 0, 8.01, '2026-08-22 01:37:44', '2026-08-22 01:37:44');
