UPDATE "recommendations" SET "tmdb_id"=2039, "imdb_id"='tt0093565', "igdb_id"=NULL, "title"='Moonstruck', "original_title"='Moonstruck', "media_type"='movie', "release_year"=1987, "poster_url"='https://image.tmdb.org/t/p/w500/2mnVWpvsHEHHnfvLn1NXYVvBGl5.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/5RQ5SIcrtKeUYeYeJLRTljR8LcN.jpg', "overview"='37-year-old Italian-American widow Loretta Castorini believes she is unlucky in love, and so accepts a marriage proposal from her boyfriend Johnny, even though she doesn''t love him. When she meets his estranged younger brother Ronny, an emotional and passionate man, she finds herself drawn to him. She tries to resist, but Ronny, who blames his brother for the loss of his hand, has no scruples about aggressively pursuing her while Johnny is out of the country. As Loretta falls for Ronny, she learns that she''s not the only one in her family with a secret romance.', "external_url"=NULL, "platforms"=NULL, "popularity"=5.3208, "vote_average"=6.838, "is_ambiguous"=0, "evidence_score"=1.49308333333333322e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-22 01:37:44' WHERE "id"=124;
