UPDATE "recommendations" SET "tmdb_id"=454, "imdb_id"='tt0117509', "igdb_id"=NULL, "title"='Romeo + Juliet', "original_title"='Romeo + Juliet', "media_type"='movie', "release_year"=1996, "poster_url"='https://image.tmdb.org/t/p/w500/dJCDUkXhfRdc4q8e4VCKEBbqzBT.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/m0miV65ZZIp13TNHJSRUF6vmCos.jpg', "overview"='In this contemporary take on William Shakespeare''s classic tragedy, the Montagues and Capulets have moved their ongoing feud to the sweltering suburb of Verona Beach, where Romeo and Juliet fall in love and secretly wed. Though the film is visually modern, the bard''s dialogue remains.', "external_url"=NULL, "platforms"=NULL, "popularity"=8.7965, "vote_average"=6.78, "is_ambiguous"=0, "evidence_score"=3.88031428571428591e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-22 01:37:44' WHERE "id"=620;
UPDATE "recommendations" SET "tmdb_id"=8909, "imdb_id"='tt0493464', "igdb_id"=NULL, "title"='Wanted', "original_title"='Wanted', "media_type"='movie', "release_year"=2008, "poster_url"='https://image.tmdb.org/t/p/w500/njy7Pz7ZHZceO7lNfGIHKphY8Hd.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/vjwuT8EzWY96W6nrJKZNI2WJU87.jpg', "overview"='Doormat Wesley Gibson is an office worker whose life is going nowhere. He meets an attractive woman named Fox and discovers that his recently murdered father - whom Wesley never knew - belonged to the Fraternity, a secret society of assassins which takes its orders from Fate itself. Fox and Sloan, the Fraternity''s leader, teach Wesley, through intense training, to tap into dormant powers and hone his innate killing skills. Though he enjoys his newfound abilities, he begins to suspect that there is more to the Fraternity than meets the eye.', "external_url"=NULL, "platforms"=NULL, "popularity"=8.8851, "vote_average"=6.53, "is_ambiguous"=0, "evidence_score"=1.61627272727272739e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-22 01:37:44' WHERE "id"=648;
UPDATE "recommendations" SET "tmdb_id"=37735, "imdb_id"='tt1282140', "igdb_id"=NULL, "title"='Easy A', "original_title"='Easy A', "media_type"='movie', "release_year"=2010, "poster_url"='https://image.tmdb.org/t/p/w500/v5f1qO6NJnxWgONgkYg21TW39DT.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/30rvmoEBqovm723agDJ3QddWXcY.jpg', "overview"='Olive, an average high school student, sees her below-the-radar existence turn around overnight once she decides to use the school''s gossip grapevine to advance her social standing. Now her classmates are turning against her and the school board is becoming concerned, including her favorite teacher and the distracted guidance counselor. With the support of her hilariously idiosyncratic parents and a little help from a long-time crush, Olive attempts to take on her notorious new identity and crush the rumor mill once and for all.', "external_url"=NULL, "platforms"=NULL, "popularity"=11.2755, "vote_average"=6.8, "is_ambiguous"=0, "evidence_score"=1.70683333333333351e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-22 01:37:44' WHERE "id"=654;
