UPDATE "recommendations" SET "tmdb_id"=65086, "imdb_id"='tt1596365', "igdb_id"=NULL, "title"='The Woman in Black', "original_title"='The Woman in Black', "media_type"='movie', "release_year"=2012, "poster_url"='https://image.tmdb.org/t/p/w500/nghQnDZE4EsQJ4J4zxR3UqItTpO.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/jJ3yFKs6xeVGxtmm7GXZYQ3XAvz.jpg', "overview"='The story follows a young lawyer, Arthur Kipps, who is ordered to travel to a remote village and sort out a recently deceased client’s papers. As he works alone in the client’s isolated house, Kipps begins to uncover tragic secrets, his unease growing when he glimpses a mysterious woman dressed only in black. Receiving only silence from the locals, Kipps is forced to uncover the true identity of the Woman in Black on his own, leading to a desperate race against time when he discovers her true identity.', "external_url"=NULL, "platforms"=NULL, "popularity"=3.9988, "vote_average"=6.144, "is_ambiguous"=0, "evidence_score"=2.6169090909090908e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-22 01:37:44' WHERE "id"=849;
UPDATE "recommendations" SET "tmdb_id"=1272, "imdb_id"='tt0448134', "igdb_id"=NULL, "title"='Sunshine', "original_title"='Sunshine', "media_type"='movie', "release_year"=2007, "poster_url"='https://image.tmdb.org/t/p/w500/oKGGeJ8qvm0UmClz43VJ31fzPP7.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/5AIAnucJKZ3sHpm7r1ykFVIoUHK.jpg', "overview"='Fifty years into the future, the sun is dying, and Earth is threatened by arctic temperatures. A team of astronauts is sent to revive the Sun — but the mission fails. Seven years later, a new team is sent to finish the mission as mankind’s last hope.', "external_url"=NULL, "platforms"=NULL, "popularity"=7.2488, "vote_average"=6.974, "is_ambiguous"=0, "evidence_score"=40.3571052631579, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-22 01:37:44' WHERE "id"=856;
UPDATE "recommendations" SET "tmdb_id"=11866, "imdb_id"='tt0377062', "igdb_id"=NULL, "title"='Flight of the Phoenix', "original_title"='Flight of the Phoenix', "media_type"='movie', "release_year"=2004, "poster_url"='https://image.tmdb.org/t/p/w500/pcj6unMsKCw0ogWFlUXmbc9gKap.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/mWXU29QjfjEG37d0c2hE11MWRGq.jpg', "overview"='When an oil rig in the Gobi Desert of Mongolia proves unproductive, an aircraft crew are sent to shut the operation down and fly them out. On the flight out over the desert on the way to Beijing, Capt. Frank Towns and co-pilot A.J. are unable to keep their cargo plane, a C-119 Flying Boxcar, in the air when a violent sandstorm strikes. Crash-landing in a remote uncharted part of the desert, the two pilots and their passengers -- a crew of oil workers and a drifter -- must work together to survive by rebuilding the aircraft. Soon, low supplies and a band of merciless smugglers add even greater urgency to their task.', "external_url"=NULL, "platforms"=NULL, "popularity"=5.5727, "vote_average"=6.0, "is_ambiguous"=0, "evidence_score"=8.84499999999999886e+00, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-22 01:37:44' WHERE "id"=863;
UPDATE "recommendations" SET "tmdb_id"=10227, "imdb_id"='tt0062136', "igdb_id"=NULL, "title"='PlayTime', "original_title"='PlayTime', "media_type"='movie', "release_year"=1967, "poster_url"='https://image.tmdb.org/t/p/w500/kQOrS0DLUXYsqPMedM2G6NJcJBq.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/pKX8G6IN8ZCRvKeHh6ctqoHZl0K.jpg', "overview"='Clumsy Monsieur Hulot finds himself perplexed by the intimidating complexity of a gadget-filled Paris. He attempts to meet with a business contact but soon becomes lost. His roundabout journey parallels that of an American tourist, and as they weave through the inventive urban environment, they intermittently meet, developing an interest in one another. They eventually get together at a chaotic restaurant, along with several other quirky characters.', "external_url"=NULL, "platforms"=NULL, "popularity"=3.7514, "vote_average"=7.7, "is_ambiguous"=0, "evidence_score"=1.85578571428571414e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-22 01:37:44' WHERE "id"=867;
UPDATE "recommendations" SET "tmdb_id"=185, "imdb_id"='tt0066921', "igdb_id"=NULL, "title"='A Clockwork Orange', "original_title"='A Clockwork Orange', "media_type"='movie', "release_year"=1971, "poster_url"='https://image.tmdb.org/t/p/w500/4sHeTAp65WrSSuc05nRBKddhBxO.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/nLFxvLokHe3bQmrmAfljIfax2jQ.jpg', "overview"='In a near-future Britain, young Alexander DeLarge and his pals get their kicks beating and raping anyone they please. When not destroying the lives of others, Alex swoons to the music of Beethoven. The state, eager to crack down on juvenile crime, gives an incarcerated Alex the option to undergo an invasive procedure that''ll rob him of all personal agency. In a time when conscience is a commodity, can Alex change his tune?', "external_url"=NULL, "platforms"=NULL, "popularity"=13.2023, "vote_average"=8.175, "is_ambiguous"=0, "evidence_score"=2.94192307692307721e+01, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-22 01:37:44' WHERE "id"=871;
