UPDATE "recommendations" SET "tmdb_id"=890, "imdb_id"='tt0112159', "igdb_id"=NULL, "title"='Neon Genesis Evangelion', "original_title"='新世紀エヴァンゲリオン', "media_type"='tv', "release_year"=1995, "poster_url"='https://image.tmdb.org/t/p/w500/y2ah9t0navXyIvoHg1uIbIHO3tt.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/z2RumCOIZ6HO3oMvfINzZlFnPAw.jpg', "overview"='At the turn of the century, the Angels returned to Earth, seeking to wipe out humanity in an apocalyptic fury. Devastated, mankind''s last remnants moved underground to wait for the day when the Angels would come back to finish the job. Fifteen years later, that day has come... but this time, humanity is ready to fight back with terrifying bio-mechanical weapons known as the Evangelions. Watch as Shinji, Rei, Asuka and the rest of the mysterious shadow agency Nerv battle to save earth from total annihilation.', "external_url"=NULL, "platforms"=NULL, "popularity"=22.9935, "vote_average"=8.564, "is_ambiguous"=0, "evidence_score"=22.4055, "created_at"='2026-07-15 12:01:52', "updated_at"='2026-08-22 01:37:44' WHERE "id"=1671;
