UPDATE "recommendations" SET "tmdb_id"=4613, "imdb_id"='tt0185906', "igdb_id"=NULL, "title"='Band of Brothers', "original_title"='Band of Brothers', "media_type"='tv', "release_year"=2001, "poster_url"='https://image.tmdb.org/t/p/w500/pGzV187ogXzgJrvPRy2YPi29ofH.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/2yDV0xLyqW88dn5qE7YCRnoYmfy.jpg', "overview"='Drawn from interviews with survivors of Easy Company, as well as their journals and letters, Band of Brothers chronicles the experiences of these men from paratrooper training in Georgia through the end of the war. As an elite rifle company parachuting into Normandy early on D-Day morning, participants in the Battle of the Bulge, and witness to the horrors of war, the men of Easy knew extraordinary bravery and extraordinary fear - and became the stuff of legend. Based on Stephen E. Ambrose''s acclaimed book of the same name.', "external_url"=NULL, "platforms"=NULL, "popularity"=36.6081, "vote_average"=8.596, "is_ambiguous"=0, "evidence_score"=9.317499999999999e+00, "created_at"='2026-07-20 01:02:04', "updated_at"='2026-08-22 01:37:44' WHERE "id"=3177;
