UPDATE "recommendations" SET "tmdb_id"=10376, "imdb_id"='tt0120731', "igdb_id"=NULL, "title"='The Legend of 1900', "original_title"='La leggenda del pianista sull''oceano', "media_type"='movie', "release_year"=1998, "poster_url"='https://image.tmdb.org/t/p/w500/iOcbJ5pxokOPDRgieVDbsFMrCc6.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/muSeX7fnNw0pv4zHK7RSwZln6Hk.jpg', "overview"='Musician Max Tooney goes to sell his prized Conn trumpet to a music shop, where he plays the instrument one last time. The shopkeeper recognises the song as one on a record matrix he found and asks who the piece is by. Tooney tells the story of an infant found abandoned in the first class dining room of the four-stacker ocean-liner SS Virginian on 1 January 1900. Danny Boodman, a coal-man from the boiler room, names the boy Danny Boodman T. D. Lemon 1900, after himself, the fruit crate the boy was found in, and the year, and raises him as his own.', "external_url"=NULL, "platforms"=NULL, "popularity"=7.2767, "vote_average"=8.24, "is_ambiguous"=0, "evidence_score"=6.505, "created_at"='2026-07-20 01:02:04', "updated_at"='2026-08-22 01:37:44' WHERE "id"=3350;
UPDATE "recommendations" SET "tmdb_id"=46837, "imdb_id"='tt1523483', "igdb_id"=NULL, "title"='Kaboom', "original_title"='Kaboom', "media_type"='movie', "release_year"=2010, "poster_url"='https://image.tmdb.org/t/p/w500/vIbX9X6lMdbdqYfuxxsHvi9n01v.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/kPsmN62vFuJD3FjFIRZXO84tKQI.jpg', "overview"='Smith, a typical young college student who likes partying and engaging in acts of random sex and debauchery, has been having some interesting dreams revolving around two gorgeous women -- and is shocked when he meets the dream girls in real life. Lorelei looks just like his fantasy brunette, while a mysterious red-haired girl being chased by assassins draws him into an international conspiracy. Or is it all just a drug-induced hallucination?', "external_url"=NULL, "platforms"=NULL, "popularity"=2.3086, "vote_average"=5.577, "is_ambiguous"=0, "evidence_score"=12.2275, "created_at"='2026-07-20 01:02:04', "updated_at"='2026-08-22 01:37:44' WHERE "id"=3364;
