UPDATE "recommendations" SET "tmdb_id"=21, "imdb_id"='tt0060371', "igdb_id"=NULL, "title"='The Endless Summer', "original_title"='The Endless Summer', "media_type"='movie', "release_year"=1966, "poster_url"='https://image.tmdb.org/t/p/w500/jDdntrv2j64KB0Zpr63cko4Mebt.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/uNRfK14Ga8Hwfqt07vo8nvWQN1i.jpg', "overview"='Bruce Brown''s The Endless Summer is one of the first and most influential surf movies of all time. The film documents American surfers Mike Hynson and Robert August as they travel the world during California’s winter (which, back in 1965 was off-season for surfing) in search of the perfect wave and ultimately, an endless summer.', "external_url"=NULL, "platforms"=NULL, "popularity"=1.9125, "vote_average"=7.162, "is_ambiguous"=0, "evidence_score"=12.47125, "created_at"='2026-07-20 01:02:04', "updated_at"='2026-08-22 01:37:44' WHERE "id"=3454;
UPDATE "recommendations" SET "tmdb_id"=43096, "imdb_id"='tt0052847', "igdb_id"=NULL, "title"='Gidget', "original_title"='Gidget', "media_type"='movie', "release_year"=1959, "poster_url"='https://image.tmdb.org/t/p/w500/i4aRCd5sRzYLb3TLm8iiUN0iJTr.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/l1iQ1hkFYzKT2GyBIldCuJutYyM.jpg', "overview"='Due to an accident while swimming in the sea, Francis meets the surfer Moondoggie. She''s fascinated with his sport and starts to hang out with his clique. Although they make fun of her at first, they teach her to surf and soon she''s accepted and given the nickname "Gidget". But it''s hard work to become more than a friend to Moondoggie.', "external_url"=NULL, "platforms"=NULL, "popularity"=1.7589, "vote_average"=5.977, "is_ambiguous"=0, "evidence_score"=1.10842857142857145e+01, "created_at"='2026-07-20 01:02:04', "updated_at"='2026-08-22 01:37:44' WHERE "id"=3457;
