UPDATE "recommendations" SET "tmdb_id"=198375, "imdb_id"='tt2591814', "igdb_id"=NULL, "title"='The Garden of Words', "original_title"='言の葉の庭', "media_type"='movie', "release_year"=2013, "poster_url"='https://image.tmdb.org/t/p/w500/mXUCVq3HMtS4Y9IQ8vmEOPyN0vH.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/qMNmdJG0WFNXcI6hfZMQH0geHc5.jpg', "overview"='Takao, who is training to become a shoemaker, skipped school and is sketching shoes in a Japanese-style garden. He meets a mysterious woman, Yukino, who is older than him. Then, without arranging the times, the two start to see each other again and again, but only on rainy days. They deepen their relationship and open up to each other. But the end of the rainy season soon approaches.', "external_url"=NULL, "platforms"=NULL, "popularity"=5.2156, "vote_average"=7.588, "is_ambiguous"=0, "evidence_score"=1.30885714285714271e+01, "created_at"='2026-07-20 04:02:06', "updated_at"='2026-08-22 01:37:44' WHERE "id"=3708;
