UPDATE "recommendations" SET "tmdb_id"=568467, "imdb_id"='tt7983894', "igdb_id"=NULL, "title"='Ammonite', "original_title"='Ammonite', "media_type"='movie', "release_year"=2020, "poster_url"='https://image.tmdb.org/t/p/w500/5lx4pUHWZoOKJWsVsvurRRNW9FK.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/23wCZgZ3mDtATocmy1lXNLM7pyx.jpg', "overview"='In 1840s England, palaeontologist Mary Anning and a young woman sent by her husband to convalesce by the sea develop an intense relationship. Despite the chasm between their social spheres and personalities, Mary and Charlotte discover they can each offer what the other has been searching for: the realisation that they are not alone. It is the beginning of a passionate and all-consuming love affair that will defy all social bounds and alter the course of both lives irrevocably.', "external_url"=NULL, "platforms"=NULL, "popularity"=5.1544, "vote_average"=6.899, "is_ambiguous"=0, "evidence_score"=8.64166666666666571e+00, "created_at"='2026-08-04 03:20:13', "updated_at"='2026-08-22 01:37:44' WHERE "id"=7014;
