UPDATE "recommendations" SET "tmdb_id"=2303, "imdb_id"='tt0062568', "igdb_id"=NULL, "title"='Hawaii Five-O', "original_title"='Hawaii Five-O', "media_type"='tv', "release_year"=1968, "poster_url"='https://image.tmdb.org/t/p/w500/8iFAlqhfY1D0ithTrfKTxObPlUH.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/9as2hYKrhbKWj4ePtFMftQfEsEX.jpg', "overview"='Hawaii Five-O is an American police procedural drama series produced by CBS Productions and Leonard Freeman. Set in Hawaii, the show originally aired for 12 seasons from 1968 to 1980, and continues in reruns. Jack Lord portrayed Detective Lieutenant Steve McGarrett, the head of a special state police task force which was based on an actual unit that existed under martial law in the 1940s. The theme music composed by Morton Stevens became especially popular. Many episodes would end with McGarrett instructing his subordinate to "Book ''em, Danno!", sometimes specifying a charge such as "murder one".', "external_url"=NULL, "platforms"=NULL, "popularity"=50.7166, "vote_average"=7.191, "is_ambiguous"=0, "evidence_score"=1.03533333333333334e+01, "created_at"='2026-08-06 03:21:21', "updated_at"='2026-08-22 01:37:44' WHERE "id"=7865;
