UPDATE "recommendations" SET "tmdb_id"=NULL, "imdb_id"=NULL, "igdb_id"=320, "title"='S.T.A.L.K.E.R.: Shadow of Chernobyl', "original_title"='S.T.A.L.K.E.R.: Shadow of Chernobyl', "media_type"='game', "release_year"=2007, "poster_url"='https://images.igdb.com/igdb/image/upload/t_cover_big/coa4s4.jpg', "backdrop_url"=NULL, "overview"='S.T.A.L.K.E.R.: Shadow of Chernobyl is a first-person shooter with role-playing and survival elements, and the first game in the S.T.A.L.K.E.R. series. It is set in an open, hazardous area known as the Zone, based on the Chernobyl exclusion zone, where players explore wilderness, settlements, and military sites in search of valuable artifacts. Beyond combat against human factions and mutated creatures, players must contend with pockets of altered physics called anomalies, radiation, hunger, and bleeding, managing supplies and equipment to survive. A non-linear storyline offers multiple endings, and limited trading and dialogue with other characters shape the experience.', "external_url"='https://www.igdb.com/games/s-t-a-l-k-e-r-shadow-of-chernobyl', "platforms"='["PlayStation 4", "PC (Microsoft Windows)", "Xbox One", "Nintendo Switch"]', "popularity"=NULL, "vote_average"=NULL, "is_ambiguous"=0, "evidence_score"=6.275, "created_at"='2026-08-07 03:39:39', "updated_at"='2026-08-22 01:37:44' WHERE "id"=8056;
