UPDATE "recommendations" SET "tmdb_id"=9567, "imdb_id"='tt0314353', "igdb_id"=NULL, "title"='Tears of the Sun', "original_title"='Tears of the Sun', "media_type"='movie', "release_year"=2003, "poster_url"='https://image.tmdb.org/t/p/w500/fUnSSQukwTwBSdCbufEE36petLq.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/cMkUwVCe6dpQnDqDwn0KwyBB2iv.jpg', "overview"='Navy SEAL Lieutenant A.K. Waters and his elite squadron of tactical specialists are forced to choose between their duty and their humanity, between following orders by ignoring the conflict that surrounds them, or finding the courage to follow their conscience and protect a group of innocent refugees. When the democratic government of Nigeria collapses and the country is taken over by a ruthless military dictator, Waters, a fiercely loyal and hardened veteran is dispatched on a routine mission to retrieve a Doctors Without Borders physician.', "external_url"=NULL, "platforms"=NULL, "popularity"=10.1319, "vote_average"=6.896, "is_ambiguous"=0, "evidence_score"=12.848, "created_at"='2026-08-17 16:08:12', "updated_at"='2026-08-22 01:37:44' WHERE "id"=10090;
