UPDATE "recommendations" SET "tmdb_id"=41577, "imdb_id"='tt0114690', "igdb_id"=NULL, "title"='Tokyo Fist', "original_title"='東京フィスト', "media_type"='movie', "release_year"=1995, "poster_url"='https://image.tmdb.org/t/p/w500/uHlZjow4nLoS37zzZ1PKUmQuhDK.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/2lVqVJkP2xvGnnIXUFLVEjcJnPL.jpg', "overview"='A businessman, Tsuda, runs into a childhood friend, Kojima, on the subway. Kojima is working as a semiprofessional boxer. Tsuda soon begins to suspect that Kojima might be having an affair with his fiancée Hizuru. After an altercation, Tsuda begins training rigorously himself, leading to an extremely bloody, violent confrontation.', "external_url"=NULL, "platforms"=NULL, "popularity"=2.4547, "vote_average"=6.8, "is_ambiguous"=0, "evidence_score"=8.77, "created_at"='2026-08-17 16:08:12', "updated_at"='2026-08-22 01:37:44' WHERE "id"=10148;
UPDATE "recommendations" SET "tmdb_id"=NULL, "imdb_id"=NULL, "igdb_id"=19817, "title"='Scorn', "original_title"='Scorn', "media_type"='game', "release_year"=2022, "poster_url"='https://images.igdb.com/igdb/image/upload/t_cover_big/co4v5c.jpg', "backdrop_url"=NULL, "overview"='Scorn is an atmospheric first person horror adventure game set in a nightmarish universe of odd forms and somber tapestry. It is designed around an idea of "being thrown into the world". Isolated and lost inside this dream-like world you will explore different interconnected regions in a non-linear fashion. The unsettling environment is a character itself. Every location contains its own theme (story), puzzles and characters that are integral in creating a cohesive lived in world. Throughout the game you will open up new areas, acquire different skill sets, weapons, various items and try to comprehend the sights presented to you.', "external_url"='https://www.igdb.com/games/scorn', "platforms"='["Xbox Series X|S", "PC (Microsoft Windows)", "PlayStation 5"]', "popularity"=NULL, "vote_average"=NULL, "is_ambiguous"=0, "evidence_score"=5.76, "created_at"='2026-08-18 01:44:45', "updated_at"='2026-08-22 01:37:44' WHERE "id"=10187;
UPDATE "recommendations" SET "tmdb_id"=43593, "imdb_id"='tt0464154', "igdb_id"=NULL, "title"='Piranha 3D', "original_title"='Piranha 3D', "media_type"='movie', "release_year"=2010, "poster_url"='https://image.tmdb.org/t/p/w500/lMLS2OFBbNYMSB1ZbVp4q2S4zTU.jpg', "backdrop_url"='https://image.tmdb.org/t/p/original/AF0PiDItegyUtlBGDMGlSQbtro.jpg', "overview"='Each year the population of sleepy Lake Victoria, Arizona explodes from 5,000 to 50,000 residents for the annual Spring Break celebration. But then, an earthquake opens an underwater chasm, releasing an enormous swarm of ancient Piranha that have been dormant for thousands of years, now with a taste for human flesh. This year, there''s something more to worry about than the usual hangovers and complaints from locals, a new type of terror is about to be cut loose on Lake Victoria.', "external_url"=NULL, "platforms"=NULL, "popularity"=7.929, "vote_average"=5.422, "is_ambiguous"=0, "evidence_score"=1.21966666666666654e+01, "created_at"='2026-08-18 01:44:45', "updated_at"='2026-08-22 01:37:44' WHERE "id"=10204;
UPDATE "recommendations" SET "tmdb_id"=NULL, "imdb_id"=NULL, "igdb_id"=30225, "title"='Kenshi', "original_title"='Kenshi', "media_type"='game', "release_year"=2018, "poster_url"='https://images.igdb.com/igdb/image/upload/t_cover_big/coclf6.jpg', "backdrop_url"=NULL, "overview"='A free-roaming squad based RPG. Focusing on open-ended sandbox gameplay features rather than a linear story. Be a trader, a thief, a rebel, a warlord, an adventurer, a farmer, a slave, or just food for the cannibals. Research new equipment and craft new gear. Purchase and upgrade your own buildings to use as safe fortified havens when things go bad, or use them to start up a business. Aid or oppose the various factions in the world while striving for the strength and wealth necessary to simply survive in the harsh desert. Train your men up from puny victims to master warriors. Carry your wounded squad mates to safety and get them all home alive.', "external_url"='https://www.igdb.com/games/kenshi', "platforms"='["PC (Microsoft Windows)"]', "popularity"=NULL, "vote_average"=NULL, "is_ambiguous"=0, "evidence_score"=1.10233333333333334e+01, "created_at"='2026-08-18 01:44:45', "updated_at"='2026-08-22 01:37:44' WHERE "id"=10235;
